/** Every band's value on one frame, clamped at both ends. */
export const bandsAt = (frame: number): readonly number[] => {
  const f = Math.max(0, Math.min(BANDS[0].length - 1, Math.round(frame)));
  return BANDS.map((band) => band[f]);
};
